SELECT 'v' AS k, v.tender_id, v.seq, v.published_at, v.notice_subtype, v.caused_by_notice_id, v.publication_id, NULL AS a, NULL AS b, NULL AS c FROM tender_versions v WHERE v.tender_id = 878700 AND v.seq BETWEEN 358 AND 362 UNION ALL SELECT 'v', v.tender_id, v.seq, v.published_at, v.notice_subtype, v.caused_by_notice_id, v.publication_id, NULL, NULL, NULL FROM tender_versions v WHERE v.tender_id = 1139127 AND v.seq BETWEEN 1 AND 5 UNION ALL SELECT 't', t.id, t.current_seq, t.current_published_at, t.source, t.current_value_eur_cents, t.current_value_currency, t.current_value_cents, t.current_value_derivation, t.projection_epoch FROM tenders t WHERE t.id = 878700 UNION ALL SELECT 't', t.id, t.current_seq, t.current_published_at, t.source, t.current_value_eur_cents, t.current_value_currency, t.current_value_cents, t.current_value_derivation, t.projection_epoch FROM tenders t WHERE t.id = 1139127 
SELECT x.tender_id, x.seq, x.lot_id, x.field, x.cents, x.currency, x.tax_basis, x.eur_cents, x.quality FROM tender_version_amounts x WHERE x.tender_id = 878700 AND x.seq BETWEEN 359 AND 360 UNION ALL SELECT x.tender_id, x.seq, x.lot_id, x.field, x.cents, x.currency, x.tax_basis, x.eur_cents, x.quality FROM tender_version_amounts x WHERE x.tender_id = 1139127 AND x.seq BETWEEN 2 AND 3 
SELECT 'lot' AS k, lb.tender_id, lb.lot_id, (SELECT group_concat(c.cursor || ':' || COALESCE(c.version_seq, '-') || ':' || c.op || ':' || c.changed_at, ' ') FROM changes c WHERE c.entity_kind = 'lot' AND c.entity_id = lb.lot_id AND c.changed_at >= 1792281600) AS rows FROM tender_version_lots lb WHERE lb.tender_id = 878700 AND lb.seq = 360 UNION ALL SELECT 'lot', lb.tender_id, lb.lot_id, (SELECT group_concat(c.cursor || ':' || COALESCE(c.version_seq, '-') || ':' || c.op || ':' || c.changed_at, ' ') FROM changes c WHERE c.entity_kind = 'lot' AND c.entity_id = lb.lot_id AND c.changed_at >= 1792281600) FROM tender_version_lots lb WHERE lb.tender_id = 1139127 AND lb.seq = 3 UNION ALL SELECT 'tender', 878700, NULL, (SELECT group_concat(c.cursor || ':' || COALESCE(c.version_seq, '-') || ':' || c.op || ':' || c.changed_at, ' ') FROM changes c WHERE c.entity_kind = 'tender' AND c.entity_id = 878700 AND c.changed_at >= 1792281600) UNION ALL SELECT 'tender', 1139127, NULL, (SELECT group_concat(c.cursor || ':' || COALESCE(c.version_seq, '-') || ':' || c.op || ':' || c.changed_at, ' ') FROM changes c WHERE c.entity_kind = 'tender' AND c.entity_id = 1139127 AND c.changed_at >= 1792281600) 
